            BigDecimal amount = tieredFee(approved);
            BigDecimal diff = amount.subtract(previous.getOrDefault(farmer, BigDecimal.ZERO));
            amountByFarmer.put(farmer, amount);
            diffByFarmer.put(farmer, diff);
            total = total.add(amount);
        }
